const REPORT_TIME_ZONE = "Asia/Riyadh";
const localDateKey = (value: Date = new Date()) => {
  const parts = new Intl.DateTimeFormat("en-GB", { timeZone: REPORT_TIME_ZONE, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(value);
  const part = (type: string) => parts.find((item) => item.type === type)?.value || "00";
  return `${part("year")}-${part("month")}-${part("day")}`;
};
const today = () => localDateKey();
const numberValue = (value: unknown) => Number(value || 0) || 0;
const rowPairs = (row: any) => numberValue(row.productionDozen) * 12 + numberValue(row.productionPairs);
const handoverPairs = (row: any) => numberValue(row.quantityDozen) * 12 + numberValue(row.quantityPairs ?? row.quantityPair);
const shortagePairs = (row: any) => numberValue(row.shortageDozen) * 12 + numberValue(row.shortagePairs);
const deliveredHandoverPairs = (row: any) => Math.max(0, handoverPairs(row) - shortagePairs(row));
const quantityLabel = (pairs: number, isAr = true) => `${Math.floor(Math.max(0, pairs) / 12)} ${isAr ? "درزن" : "dozen"} + ${Math.max(0, pairs) % 12} ${isAr ? "زوج" : "pairs"}`;
const signedQuantityLabel = (pairs: number, isAr = true) => {
  const sign = pairs > 0 ? "+" : pairs < 0 ? "−" : "±";
  return `${sign}${quantityLabel(Math.abs(pairs), isAr)}`;
};
const rowYarnTotalBy = (row: any, key: string) => numberValue(row[key]) * rowPairs(row);
const rowYarnTotal = (row: any) => ["yarnRubber", "yarnSpandex", "yarnNylon", "yarnCotton", "yarnBamboo", "yarnSpan"].reduce((sum, key) => sum + rowYarnTotalBy(row, key), 0);
const rowWastePercent = (row: any) => { const used = rowYarnTotal(row); return used > 0 ? ((numberValue(row.wasteThreadGrams) + numberValue(row.wasteSocksGrams)) / used * 100).toFixed(2) : "0.00"; };
const dateOnly = (value: unknown) => {
  if (!value) return "";
  const text = String(value);
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? text.slice(0, 10) : localDateKey(parsed);
};
const displayTime = (value: unknown, isAr = true) => { if (!value) return isAr ? "غير مسجل" : "Not recorded"; const text = String(value); if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return isAr ? "غير مسجل" : "Not recorded"; const parsed = new Date(text); return Number.isNaN(parsed.getTime()) ? (isAr ? "غير مسجل" : "Not recorded") : parsed.toLocaleString(isAr ? "ar-SA" : "en-US", { timeZone: REPORT_TIME_ZONE, dateStyle: "short", timeStyle: "short" }); };
const elapsedLabel = (minutes: number | null, isAr = true) => {
  if (minutes === null || !Number.isFinite(minutes)) return isAr ? "غير محسوبة" : "Not calculated";
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  return `${hours ? `${hours} ${isAr ? "ساعة" : "hour(s)"} ` : ""}${mins} ${isAr ? "دقيقة" : "minute(s)"}`;
};
const escapeHtml = (value: unknown) => String(value ?? "").replace(/[&<>\"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" } as Record<string, string>)[c] || c);

